import type { Currency } from './currency-model';

export interface Opportunity {
  /**
   * @displayName Opportunity
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Opportunity ID
   * @description Human-readable record identifier
   */
  opportunityID: string;
  /**
   * @displayName Architect
   */
  architect?: string;
  /**
   * @displayName Clearance level
   */
  clearanceLevelKey?: string;
  /**
   * @displayName Currency
   */
  currency?: Pick<Currency, 'id' | 'currencyName'>;
  /**
   * @displayName Duration
   */
  duration?: string;
  /**
   * @displayName Entry Type
   */
  entryType?: string;
  /**
   * @displayName Exchange Rate
   */
  exchangeRate?: number;
  /**
   * @displayName Opportunity Name
   * @validationRule Required for create/update operations
   */
  opportunityName: string;
  /**
   * @displayName Price to Win
   */
  priceToWin?: number;
  /**
   * @displayName Price to Win (Base)
   */
  priceToWinBase?: number;
  /**
   * @displayName Project End Date
   */
  projectEndDate?: string;
  /**
   * @displayName Project Start Date
   */
  projectStartDate?: string;
  /**
   * @displayName Pursuit Lead
   */
  pursuitLead?: string;
}

export const _Opportunity = 'Opportunity' as const;